  .tk-k { color: var(--violet); }
  .tk-f { color: var(--teal); }
  .tk-s { color: #a5e075; }
  .tk-n { color: var(--accent-2); }
  .tk-c { color: var(--text-faint); font-style: italic; }
  .tk-o { color: var(--text-dim); }

  .result-table {
    border-top: 1px solid var(--border);
