  .result-table .row { display: grid; grid-template-columns: 1.4fr 1fr 1fr 1fr; gap: 12px; padding: 5px 0; }
  .result-table .row.head { color: var(--text-faint); border-bottom: 1px dashed var(--border); margin-bottom: 4px; padding-bottom: 8px; }
  .result-table .meta { margin-top: 10px; color: var(--ok); font-size: 0.78rem; }

  /* LOGO STRIP */
  .strip {
    padding: 36px 0;
    border-block: 1px solid var(--border);
    background: rgba(255,255,255,0.01);
  }
  .strip-label {
    text-align: center;
    color: var(--text-faint);
    font-size: 0.82rem;
