    font-size: 1.05rem;
    letter-spacing: -0.01em;
  }
  .strip-row span { opacity: .75; transition: opacity .2s; }
  .strip-row span:hover { opacity: 1; color: var(--text-dim); }

  /* STATS */
  .stats {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    border: 1px solid var(--border);
    border-radius: var(--radius);
