    overflow: hidden;
  }
  .stat {
    padding: 34px 28px;
    border-right: 1px solid var(--border);
  }
  .stat:last-child { border-right: none; }
  .stat .num {
    font-size: 2.6rem;
    font-weight: 750;
    letter-spacing: -0.03em;
    line-height: 1;
    margin-bottom: 10px;
