    grid-template-columns: 1fr 1fr;
    gap: 64px;
    align-items: start;
  }
  .problem-list { list-style: none; display: grid; gap: 18px; }
  .problem-list li {
    display: grid;
    grid-template-columns: 36px 1fr;
    gap: 14px;
    padding: 20px;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: var(--bg-card);
  }
  .problem-list .x {
    width: 36px; height: 36px;
    border-radius: 9px;
    background: rgba(255,90,90,0.1);
    color: #ff7a7a;
    display: grid; place-items: center;
    font-family: var(--mono);
    font-weight: 700;
  }
  .problem-list h4 { font-size: 1rem; margin-bottom: 4px; }
  .problem-list p { color: var(--text-dim); font-size: 0.93rem; }

  /* ARCHITECTURE */
  .arch {
    background: var(--bg-elev);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 36px;
  }
  .arch svg { width: 100%; height: auto; }

  /* FEATURES */
  .features {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
  }
  .feature {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 28px;
    transition: border-color .25s, transform .25s, background .25s;
    position: relative;
    overflow: hidden;
  }
  .feature::after {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(400px 200px at var(--mx, 50%) var(--my, 0%), rgba(245,165,36,0.08), transparent 70%);
    opacity: 0;
    transition: opacity .3s;
    pointer-events: none;
  }
  .feature:hover { border-color: var(--border-strong); transform: translateY(-3px); }
  .feature:hover::after { opacity: 1; }
  .feature .icon {
    width: 44px; height: 44px;
    border-radius: 11px;
    display: grid; place-items: center;
    background: var(--bg-elev);
    border: 1px solid var(--border-strong);
    margin-bottom: 20px;
    color: var(--accent);
  }
  .feature h3 { font-size: 1.12rem; margin-bottom: 8px; letter-spacing: -0.01em; }
  .feature p { color: var(--text-dim); font-size: 0.95rem; }

  /* CODE TABS */
  .tabs-wrap {
    display: grid;
    grid-template-columns: 0.8fr 1.2fr;
    gap: 40px;
    align-items: start;
  }
  .tab-list { display: grid; gap: 10px; }
  .tab-btn {
    text-align: left;
    background: transparent;
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 18px 20px;
    color: var(--text-dim);
    cursor: pointer;
    font-family: var(--sans);
    transition: all .2s;
  }
  .tab-btn h4 { color: var(--text); font-size: 1rem; margin-bottom: 4px; }
  .tab-btn p { font-size: 0.9rem; }
  .tab-btn:hover { border-color: var(--border-strong); }
  .tab-btn.active {
    border-color: var(--accent);
    background: var(--bg-card);
    box-shadow: inset 3px 0 0 var(--accent);
  }
  .tab-panel { display: none; }
  .tab-panel.active { display: block; animation: fade .35s ease; }
  @keyframes fade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

  /* INTEGRATIONS */
  .integrations {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    gap: 14px;
  }
  .integ {
    border: 1px solid var(--border);
    background: var(--bg-card);
    border-radius: 12px;
    padding: 20px 14px;
    text-align: center;
    font-size: 0.9rem;
    color: var(--text-dim);
    transition: all .2s;
  }
  .integ b {
    display: block;
    font-family: var(--mono);
    font-size: 1.05rem;
    color: var(--text);
    margin-bottom: 4px;
  }
  .integ:hover { border-color: var(--accent); color: var(--text); }

  /* BENCHMARK */
  .bench {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 36px;
  }
  .bench-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 28px;
  }
  .bench-head h3 { font-size: 1.2rem; }
  .bench-head small { color: var(--text-faint); font-family: var(--mono); font-size: 0.8rem; }
  .bar-row {
    display: grid;
    grid-template-columns: 170px 1fr 90px;
    align-items: center;
    gap: 16px;
    margin-bottom: 14px;
    font-size: 0.93rem;
  }
  .bar-row .name { color: var(--text-dim); }
  .bar-row.us .name { color: var(--text); font-weight: 600; }
  .bar-track {
    height: 22px;
    background: var(--bg-elev);
    border-radius: 6px;
    overflow: hidden;
    border: 1px solid var(--border);
  }
  .bar-fill {
    height: 100%;
    width: 0;
    background: #3b4252;
    border-radius: 5px;
    transition: width 1.2s cubic-bezier(.2,.8,.2,1);
  }
  .bar-row.us .bar-fill { background: linear-gradient(90deg, var(--accent), var(--accent-2)); }
  .bar-val { font-family: var(--mono); text-align: right; color: var(--text-dim); font-size: 0.85rem; }
  .bar-row.us .bar-val { color: var(--accent-2); font-weight: 700; }
  .bench-foot { margin-top: 18px; color: var(--text-faint); font-size: 0.82rem; font-family: var(--mono); }

  /* COMPARISON */
  .table-wrap {
    overflow-x: auto;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    background: var(--bg-card);
  }
  table { width: 100%; border-collapse: collapse; min-width: 640px; }
  th, td {
    padding: 16px 20px;
    text-align: left;
    border-bottom: 1px solid var(--border);
    font-size: 0.93rem;
  }
  th { font-weight: 600; color: var(--text-dim); font-size: 0.85rem; background: var(--bg-elev); }
  th.hl, td.hl { background: rgba(245,165,36,0.06); }
  th.hl { color: var(--accent); }
  tr:last-child td { border-bottom: none; }
  td.yes { color: var(--ok); }
  td.no { color: var(--text-faint); }
  td.part { color: var(--accent-2); }

  /* TESTIMONIALS */
  .quotes {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
  }
  .quote {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 28px;
    display: flex;
    flex-direction: column;
    gap: 22px;
  }
  .quote blockquote { font-size: 0.98rem; color: var(--text); line-height: 1.6; }
  .quote .who { display: flex; align-items: center; gap: 12px; margin-top: auto; }
  .avatar {
    width: 40px; height: 40px;
    border-radius: 50%;
    display: grid; place-items: center;
    font-weight: 700;
    font-size: 0.85rem;
    color: #0b0d12;
  }
  .who b { display: block; font-size: 0.93rem; }
  .who span { color: var(--text-faint); font-size: 0.84rem; }

  /* INSTALL */
  .install-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
  }
  .install-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 28px;
  }
  .install-card h3 { font-size: 1.05rem; margin-bottom: 6px; }
  .install-card > p { color: var(--text-dim); font-size: 0.92rem; margin-bottom: 18px; }
  .code-block {
    background: var(--bg-elev);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 14px 16px;
    font-size: 0.86rem;
    color: var(--text);
    overflow-x: auto;
    white-space: pre;
    position: relative;
  }
  .code-block .prompt { color: var(--accent); user-select: none; }

  /* FAQ */
  .faq { max-width: 820px; margin: 0 auto; display: grid; gap: 12px; }
  details {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 0 22px;
    transition: border-color .2s;
  }
  details[open] { border-color: var(--border-strong); }
  summary {
    list-style: none;
    cursor: pointer;
    padding: 20px 0;
    font-weight: 600;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
  }
  summary::-webkit-details-marker { display: none; }
  summary::after {
    content: "+";
    font-family: var(--mono);
    font-size: 1.3rem;
    color: var(--accent);
    transition: transform .2s;
  }
  details[open] summary::after { transform: rotate(45deg); }
  details p { color: var(--text-dim); padding-bottom: 20px; font-size: 0.95rem; }

  /* CTA */
  .cta {
    background:
      linear-gradient(160deg, rgba(245,165,36,0.14), rgba(61,214,198,0.04) 60%),
      var(--bg-card);
    border: 1px solid var(--border-strong);
    border-radius: 22px;
    padding: 72px 40px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .cta h2 {
    font-size: clamp(2rem, 4.5vw, 3.2rem);
    letter-spacing: -0.03em;
    line-height: 1.1;
    margin-bottom: 16px;
  }
  .cta p { color: var(--text-dim); max-width: 560px; margin: 0 auto 32px; font-size: 1.05rem; }
  .cta .hero-actions { justify-content: center; margin-bottom: 0; }

  /* FOOTER */
  footer {
    border-top: 1px solid var(--border);
    padding: 64px 0 40px;
    margin-top: 40px;
    color: var(--text-dim);
    font-size: 0.92rem;
  }
  .footer-grid {
    display: grid;
    grid-template-columns: 1.6fr repeat(4, 1fr);
    gap: 40px;
    margin-bottom: 48px;
  }
  .footer-grid h5 {
    color: var(--text);
    font-size: 0.85rem;
    margin-bottom: 14px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-family: var(--mono);
  }
  .footer-grid ul { list-style: none; display: grid; gap: 10px; }
  .footer-grid a:hover { color: var(--text); }
  .footer-brand p { margin-top: 14px; max-width: 300px; color: var(--text-faint); }
  .footer-bottom {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    padding-top: 24px;
    border-top: 1px solid var(--border);
    color: var(--text-faint);
    font-size: 0.85rem;
    font-family: var(--mono);
  }

